void picking_filter() {
    if( u_enabled == 0 )
        return;
    if( gl_FragColor.a == 0.0 )
        discard;
    gl_FragColor = u_id_color;
}


uniform vec3 u_clipping_plane_pos0;
uniform vec3 u_clipping_plane_norm0;

float clip_planes(vec3 loc) {
    float distance_from_clip = 3.4e38; // max float

vec3 relative_vec0 = loc - u_clipping_plane_pos0;
float distance_from_clip0 = dot(relative_vec0, u_clipping_plane_norm0);
distance_from_clip = min(distance_from_clip0, distance_from_clip);
;
    return distance_from_clip;
}


